define('ANI_SMS_LOCAL_TEST',true);$_SERVER['REMOTE_ADDR']='127.0.0.1';putenv('ANI_SMS_TEST_WP='.dirname(__DIR__,3).'/runtime/wordpress');require __DIR__.'/bootstrap.php';
$store=new AniSms\Infrastructure\Database($wpdb);$store->migrate();$queue=new AniSms\Infrastructure\Queue($store);$now=(int)($argv[2]??time());$service=new AniSms\Cart\Service($store,$queue,static fn()=>$now);$queue->register('cart',array($service,'dispatch'));add_action('ani_sms_job_finished',function($j,$r)use($service){if('cart'===$j['module'])$service->completed($j,$r);},10,2);
if(($argv[1]??'')==='--return'){$uid=(int)$argv[3];$signal=$argv[4];$store->lock('cart-user:'.$uid,function()use($store,$service,$uid,$signal){file_put_contents($signal,'ready');usleep(1000000);$data=get_user_meta($uid,'_woocommerce_persistent_cart_'.get_current_blog_id(),true);$service->activity($uid,$data['cart']);});exit;}
if(($argv[1]??'')==='--recover'){$service->recover();exit;}if(($argv[1]??'')==='--drain'){$queue->drain();exit;}
add_filter('pre_wp_mail','__return_true');update_option('ani_sms_modules',array('auth','marketing','cart'));update_option('ani_sms_cart_settings',AniSms\Cart\Service::validate(array('cart_message'=>'{item_count} {cart_url}','cart_delay'=>'15')));
$store->query("DELETE FROM {$store->table('jobs')} WHERE module='cart'");$store->query("DELETE FROM {$store->table('carts')}");$users=array();$p=new WC_Product_Simple();$p->set_name('Cart batch fixture');$p->set_status('publish');$p->set_regular_price('100');$p->set_price('100');$p->set_stock_status('instock');$p->save();$items=array('cart'=>array('product_id'=>$p->get_id(),'variation_id'=>0,'quantity'=>1,'variation'=>array()));$sub=new AniSms\Marketing\Subscribers($store);
for($i=0;$i<21;$i++){$uid=wp_insert_user(array('user_login'=>'ani_cart_batch_'.bin2hex(random_bytes(4)),'user_pass'=>wp_generate_password(30),'role'=>'subscriber'));$users[]=$uid;$phone='+98913'.str_pad((string)(random_int(10000,99999)*100+$i),7,'0',STR_PAD_LEFT);$store->insert('identities',array('phone'=>$phone,'user_id'=>$uid,'verified_at'=>time(),'verification_mode'=>'local'));$sub->consent($uid,true,AniSms\Marketing\Subscribers::VERSION);update_user_meta($uid,'_woocommerce_persistent_cart_'.get_current_blog_id(),array('cart'=>$items));$service->preference($uid,true);$service->activity($uid,$items);}
$now+=901;$n=fn($state)=>(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$store->table('carts')} WHERE state=%s",$state));$service=new AniSms\Cart\Service($store,$queue,static fn()=>$now);$service->recover();ani_check(20===$n('queued')&&1===$n('waiting'),'scan bounded to twenty eligible carts');
$clients=function($op)use(&$now){$processes=array();for($i=0;$i<2;$i++){$p=proc_open(array(PHP_BINARY,__FILE__,$op,(string)$now),array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w')),$pipes,null,null,array('bypass_shell'=>true));if(!is_resource($p))throw new RuntimeException('Client unavailable');$processes[]=array($p,$pipes);}foreach($processes as [$p,$pipes]){fclose($pipes[0]);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0)throw new RuntimeException($err.$out);}};
$clients('--recover');ani_check(21===$n('queued'),'two real PHP clients continue without starvation');ani_check(21===(int)$wpdb->get_var("SELECT COUNT(*) FROM {$store->table('jobs')} WHERE module='cart'"),'concurrent recovery creates one job per episode');
$store->query("UPDATE {$store->table('jobs')} SET available=0 WHERE module='cart'");$clients('--drain');$clients('--drain');$service->reconcile();ani_check(21===$n('simulated'),'parallel workers simulate each cart exactly once');$before=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$store->table('jobs')} WHERE module='cart'");$service->recover();ani_check($before===(int)$wpdb->get_var("SELECT COUNT(*) FROM {$store->table('jobs')} WHERE module='cart'"),'repeated scan after sending does not duplicate');
$uid=$users[0];$store->query($wpdb->prepare("UPDATE {$store->table('carts')} SET last_attempt=0 WHERE user_id=%d",$uid));$service->activity($uid,$items);$now+=901;$service=new AniSms\Cart\Service($store,$queue,static fn()=>$now);$queue->register('cart',array($service,'dispatch'));$service->recover();$r=$service->row($uid,'local');$signal=tempnam(sys_get_temp_dir(),'ani_cart_return_');$client=proc_open(array(PHP_BINARY,__FILE__,'--return',(string)$now,(string)$uid,$signal),array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w')),$pipes,null,null,array('bypass_shell'=>true));if(!is_resource($client))throw new RuntimeException('Return client unavailable');$deadline=microtime(true)+10;while(trim(file_get_contents($signal))!=='ready'&&microtime(true)<$deadline){usleep(20000);clearstatcache(true,$signal);}ani_check(trim(file_get_contents($signal))==='ready','independent return client owns account lock');$store->query("UPDATE {$store->table('jobs')} SET available=0 WHERE module='cart'");$queue->drain();$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);foreach($pipes as $pipe)fclose($pipe);ani_check(proc_close($client)===0,'concurrent return client completed');unlink($signal);$latest=$service->row($uid,'local');$oldjob=$store->row($wpdb->prepare("SELECT state FROM {$store->table('jobs')} WHERE job_key=%s",$r['job_key']));ani_check('waiting'===$latest['state']&&$latest['revision']!==$r['revision']&&'cancelled'===$oldjob['state'],'concurrent return prevents stale dispatch without overwriting new episode');
